def(){ :; }

get_state(){ $D inspect | python3 - <<'PY'
import sys,json
j=json.load(sys.stdin)
p=j.get('playback',{})
si=p.get('songInfo') or {}
print({
  'isPlaying': p.get('isPlaying'),
  'currentIndex': p.get('currentIndex'),
  'queueLength': p.get('queueLength'),
  'title': si.get('title'),
  'positionMs': si.get('position'),
  'durationMs': si.get('duration')
})
PY
}

echo 'state: before pause'; get_state;
$D pause >/dev/null; echo 'state: after pause'; get_state;
$D resume >/dev/null; echo 'state: after resume'; get_state;
$D next >/dev/null; echo 'state: after next'; get_state;
POS_BEFORE=$($D inspect | python3 - <<'PY'
import sys,json
j=json.load(sys.stdin)
si=j['playback']['songInfo']
print(si['position'])
PY
);
$D seek 1:00 >/dev/null;
echo 'state: after seek'; get_state;
POS_AFTER=$($D inspect | python3 - <<'PY'
import sys,json
j=json.load(sys.stdin)
si=j['playback']['songInfo']
print(si['position'])
PY
);
echo "seek_delta_ms=$((POS_AFTER-POS_BEFORE))"

